// Extract Message-ID from /send-email backend response
const sendResult = $input.first().json;

// /send-email returns: { success: true, message_id: "<uuid@scambuster.local>", ts_sent: "..." }
let messageId = sendResult.message_id || '';

// Clean Message-ID (remove chevrons if present)
messageId = messageId.replace(/^<|>$/g, '').trim();

return {
  json: {
    message_id: messageId,
    thread_id: null,  // No thread concept with SMTP (Gmail-specific)
    provider_msg_id: messageId,
    ts_sent: sendResult.ts_sent || new Date().toISOString()
  }
};

// Human Delay Calculator — Log-normal distribution per scam type
// References: Kalman & Rafaeli 2005, Jiang et al. 2012
// Input: scam_category from WF-INTAKE Prepare Reply Data

const input = $input.first().json;

// Scam-type delay profiles: { mu, sigma, activeStart, activeEnd }
// mu/sigma = parameters of ln(delay_minutes) for Box-Muller log-normal
const scamProfiles = {
  // Slow: romance scams have long, drawn-out exchanges
  ROMANCE:           { mu: 4.6, sigma: 0.7, activeStart: 8,  activeEnd: 21 },
  ROMANCE_SCAM:      { mu: 4.6, sigma: 0.7, activeStart: 8,  activeEnd: 21 },
  // Professional: business fraud targets respond during work hours
  INVOICE_FRAUD:     { mu: 3.8, sigma: 0.6, activeStart: 9,  activeEnd: 18 },
  PHISH_CREDENTIALS: { mu: 3.8, sigma: 0.6, activeStart: 9,  activeEnd: 18 },
  // Casual: general scams, moderate timing
  PHISHING:          { mu: 4.0, sigma: 0.8, activeStart: 10, activeEnd: 23 },
  TECH_SUPPORT:      { mu: 4.0, sigma: 0.8, activeStart: 10, activeEnd: 23 },
  UNKNOWN:           { mu: 4.0, sigma: 0.8, activeStart: 10, activeEnd: 23 },
};

const defaultProfile = { mu: 4.0, sigma: 0.8, activeStart: 9, activeEnd: 22 };
const timezone = 'Europe/Paris';
const MIN_DELAY = 20;   // minutes (hard floor)
const MAX_DELAY = 480;  // minutes = 8 hours (hard ceiling)

// Get scam category from input
const scamCategory = (input.scam_category || 'UNKNOWN').toUpperCase();
const profile = scamProfiles[scamCategory] || defaultProfile;
const profileName = profile.mu < 4 ? 'professional' : profile.mu > 4.3 ? 'slow' : 'casual';

// Box-Muller transform for log-normal distribution
const u1 = Math.random();
const u2 = Math.random();
const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
let delayMinutes = Math.exp(profile.mu + profile.sigma * z);

// Clamp to floor/ceiling
delayMinutes = Math.max(MIN_DELAY, Math.min(MAX_DELAY, delayMinutes));

// Compute send time
let sendAt = new Date(Date.now() + delayMinutes * 60 * 1000);

// Night avoidance — correct timezone via Intl (handles DST)
const localTimeStr = sendAt.toLocaleString('en-US', { timeZone: timezone, hour12: false });
const localHour = parseInt(localTimeStr.split(', ')[1].split(':')[0], 10);

if (localHour >= profile.activeEnd || localHour < profile.activeStart) {
  // Parse current local date to compute next morning correctly
  const localDateStr = sendAt.toLocaleString('en-US', { timeZone: timezone });
  const localDate = new Date(localDateStr);

  // Move to next day if past activeEnd
  if (localHour >= profile.activeEnd) {
    localDate.setDate(localDate.getDate() + 1);
  }

  // Set to activeStart + jitter (0-30 min)
  localDate.setHours(profile.activeStart, Math.floor(Math.random() * 30), 0, 0);

  // Convert back to UTC by computing the offset
  const utcRef = new Date(sendAt.toLocaleString('en-US', { timeZone: 'UTC' }));
  const localRef = new Date(sendAt.toLocaleString('en-US', { timeZone: timezone }));
  const tzOffsetMs = utcRef.getTime() - localRef.getTime();
  sendAt = new Date(localDate.getTime() + tzOffsetMs);
}

// Safety: ensure sendAt is always in the future
if (sendAt.getTime() <= Date.now()) {
  sendAt = new Date(Date.now() + MIN_DELAY * 60 * 1000);
}

console.log(`Human delay: ${Math.round(delayMinutes)} min | Profile: ${profileName} | Scam: ${scamCategory} | Send at: ${sendAt.toISOString()}`);

return [{
  json: {
    ...input,
    _sendAt: sendAt.toISOString(),
    _delayMinutes: Math.round(delayMinutes),
    _scamCategory: scamCategory,
    _profile: profileName,
  }
}];
